<script setup>
import { ref } from 'vue'; import { useI18n } from 'vue-i18n'; import FooterContent from './footer-content.vue';
defineProps({title:{type:String,default:''}}); const emit=defineEmits(['navigate']); const {t}=useI18n();const visible=ref(false);const links=Object.freeze([{key:'nav.dashboard',icon:'pi pi-home',route:'dashboard'},{key:'nav.assets',icon:'pi pi-truck',route:'assets'},{key:'nav.maintenance',icon:'pi pi-wrench',route:'maintenance'},{key:'nav.operations',icon:'pi pi-briefcase',route:'operations'}].map(Object.freeze));
/** @param {string} route */ function navigate(route){visible.value=false;emit('navigate',route);}
</script>
<template><div class="min-h-screen flex flex-column surface-ground"><header class="surface-card border-bottom-1 surface-border"><div class="max-w-screen-xl mx-auto p-3 flex align-items-center gap-3"><pv-button icon="pi pi-bars" text rounded @click="visible=true"/><i class="pi pi-truck text-primary text-2xl"/><strong>{{t('app.name')}}</strong><span v-if="title">/ {{title}}</span></div></header><pv-drawer v-model:visible="visible" :header="t('app.name')"><nav class="flex flex-column gap-2"><pv-button v-for="link in links" :key="link.route" :label="t(link.key)" :icon="link.icon" text class="justify-content-start" @click="navigate(link.route)"/></nav></pv-drawer><main class="flex-1 max-w-screen-xl mx-auto w-full p-3 md:p-5"><slot/></main><footer-content/></div></template>
